const cache=new Map();
async function api(path,{signal}={}){requests++;let response;try{response=await fetch(API+path,{signal:AbortSignal.any([signal??AbortSignal.timeout(18000),networkController.signal]),headers:{Accept:'application/json'}})}catch(e){throw Error(e.name==='TimeoutError'?'ACME API took too long to respond. Please retry.':'Unable to reach the ACME API. Please retry.')}if(!response.ok)throw Error(response.status===404?'No matching record was found.':`ACME API returned HTTP ${response.status}. Please retry.`);let d=await response.json();if(d.error)throw Error(typeof d.error==='string'?d.error:(d.error.message||'ACME API returned an error.'));return d}
async function cached(path,ttl=25000){const key=API+path;let x=cache.get(key);if(x&&Date.now()-x.time<ttl)return x.promise;let promise=api(path);cache.set(key,{time:Date.now(),promise});try{return await promise}catch(e){cache.delete(key);throw e}}
function newestTransactions(list){return [...list].sort((a,b)=>Number(b.block_index??-1)-Number(a.block_index??-1)||Number(b.block_time??0)-Number(a.block_time??0)||Number(b.tx_index??0)-Number(a.tx_index??0)||String(a.tx_hash).localeCompare(String(b.tx_hash)))}
async function orderedTransactions(type=''){const base=API,key=base+'::ordered-transactions:'+type;const hit=cache.get(key);if(hit&&Date.now()-hit.time<25000)return hit.promise;const promise=(async()=>{const transactions=new Map(),seen=new Set();let cursor=null;do{if(API!==base)throw Error('Network changed');const path='/api/transactions?limit=1000'+(type?'&tx_type='+enc(type):'')+(cursor!==null?'&cursor='+enc(cursor):'');const page=await cached(path);for(const tx of arr(page.result))transactions.set(tx.tx_hash,tx);const next=page.next_cursor;if(next===null||next===undefined)break;if(seen.has(String(next)))throw Error('The API repeated its transaction cursor. Please refresh.');seen.add(String(next));cursor=next}while(true);return newestTransactions([...transactions.values()])})();cache.set(key,{time:Date.now(),promise});try{return await promise}catch(error){cache.delete(key);throw error}}
const blockFeeCache=new Map();
function formatFee(value){return Number.isFinite(value)?new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(value):'—'}
async function bitcoinBlockFees(block,source=API){const provider=source===NETWORKS.testnet.api?'https://mempool.space/testnet4/api/v1/block/':'https://mempool.space/api/v1/block/';const key=provider+block.block_hash;if(blockFeeCache.has(key))return blockFeeCache.get(key);const promise=(async()=>{const response=await fetch(key,{signal:AbortSignal.any([AbortSignal.timeout(15000),networkController.signal]),credentials:'omit'});if(!response.ok)throw Error('Block fee data unavailable');const data=await response.json();if(data.id!==block.block_hash||Number(data.height)!==Number(block.block_index))throw Error('Block fee data did not match the selected block');const extra=data.extras||{};return {average:Number.isFinite(extra.avgFee)?extra.avgFee:null,rate:Number.isFinite(extra.avgFeeRate)?extra.avgFeeRate:null,total:Number.isFinite(extra.totalFees)?extra.totalFees:null,count:Number.isFinite(data.tx_count)?data.tx_count:null}})();blockFeeCache.set(key,promise);try{return await promise}catch(error){blockFeeCache.delete(key);throw error}}
async function enrichBlockTiles(blocks,g){const source=API;orderedTransactions().then(transactions=>{if(g!==generation||source!==API)return;const counts=new Map();for(const tx of transactions)counts.set(Number(tx.block_index),(counts.get(Number(tx.block_index))||0)+1);for(const block of blocks){const count=counts.get(Number(block.block_index))||0;block.acme_count=count;const badge=document.querySelector('[data-acme-count="'+block.block_index+'"]');if(badge){badge.textContent=count+' ACME '+(count===1?'txn':'txns');badge.classList.toggle('has-acme',count>0);badge.closest('.block-cube')?.classList.toggle('has-acme',count>0);badge.closest('tr')?.classList.toggle('has-acme',count>0)}}updateBlockActivity(blocks);updateSelectedBlockMetrics()}).catch(()=>{if(g!==generation)return;blocks.forEach(block=>block.acme_count_error=true);document.querySelectorAll('[data-acme-count]').forEach(badge=>badge.textContent='ACME count unavailable');updateSelectedBlockMetrics()});let cursor=0;const worker=async()=>{while(cursor<blocks.length){const block=blocks[cursor++];if(g!==generation||source!==API)return;try{block.fee_stats=await bitcoinBlockFees(block,source)}catch{block.fee_error=true}if(g!==generation||source!==API)return;const fee=document.querySelector('[data-block-fee="'+block.block_index+'"]');if(fee){fee.textContent=block.fee_stats?.rate!=null?(fee.hasAttribute('data-fee-cell')?'':'Avg fee rate: ')+formatFee(block.fee_stats.rate)+' sat/vB':'Fee rate unavailable';fee.title=block.fee_stats?.rate!=null?'Average fee rate: '+formatFee(block.fee_stats.rate)+' sat/vB':'Fee statistics from mempool.space'}updateSelectedBlockMetrics()}};await Promise.all([worker(),worker(),worker()])}
function updateBlockActivity(blocks){for(const block of blocks){const bar=document.querySelector('[data-activity-block="'+block.block_index+'"]');if(!bar)continue;const count=block.acme_count;bar.classList.toggle('has-acme',count>0);const label='Block '+fmt(block.block_index)+' · '+fmt(block.transaction_count)+' Bitcoin transactions · '+(count!=null?fmt(count)+' ACME transactions':'ACME count loading');bar.title=label;bar.setAttribute('aria-label',label)}}
