async function showSelectedBlock(block,blocks,g){const panelGeneration=++blockPanelGeneration;const host=$('#selected-block-panel');if(!host)return;const selected=block?.block_index;selectedBlockMetrics=block||null;host.innerHTML=`<section class="panel selected-block"><div class="panel-head"><h2>${block?'Block #'+fmt(selected):'ACME mempool'}</h2>${block?link('block',selected,'Full block details ↗'):tag('Unconfirmed',true)}</div><div class="block-workspace"><div class="block-summary">${block?row('Block height',fmt(selected))+row('Timestamp',esc(date(block.block_time)))+row('Age',time(block.block_time))+row('Total Bitcoin transactions',fmt(block.transaction_count))+row('ACME transactions','<span id="selected-acme-count">Loading…</span>')+row('Average fee rate','<span id="selected-average-rate">Loading…</span>')+row('Total block fees','<span id="selected-total-fees">Loading…</span>')+row('Block hash',`<span class="mono">${esc(block.block_hash)}</span>${copy(block.block_hash)}`)+row('Previous block',link('block',selected-1,'#'+fmt(selected-1))):`<p class="section-description">Unconfirmed ACME events currently seen by the indexer.</p><div id="pending-summary" class="loading">Loading mempool…</div>`}</div><div class="block-activity"><h3>Recent block activity</h3><p>Bitcoin transaction counts across these ${blocks.length} indexed blocks.</p><div class="activity-legend"><span><i class="legend-acme"></i> Contains ACME transactions</span><span><i></i> Bitcoin activity</span></div><div class="activity-bars" role="group" aria-label="Transactions per Bitcoin block">${[...blocks].reverse().map(b=>`<button class="activity-bar ${b.block_index===selected?'active':''}" data-activity-block="${b.block_index}" style="--bar-height:${Math.max(3,Number(b.transaction_count||0)/Math.max(1,...blocks.map(b=>Number(b.transaction_count||0)))*100)}%" aria-label="Block ${b.block_index}: ${fmt(b.transaction_count)} Bitcoin transactions" title="Block ${fmt(b.block_index)} · ${fmt(b.transaction_count)} transactions"><span></span></button>`).join('')}</div><div class="chart-scale"><span>#${fmt(blocks[blocks.length-1].block_index)}</span><span>#${fmt(blocks[0].block_index)}</span></div></div></div><div class="block-message-head"><h3>${block?'ACME transactions in this block':'Pending ACME events'}</h3><span id="block-message-count"></span></div><div id="block-message-map" class="block-message-map"><div class="loading">Loading protocol activity…</div></div><div class="panel-note">${block?'Counts: ACME indexer. Average fee rates and total fees: mempool.space, for the whole Bitcoin block. Transaction tiles show ACME activity only.':'Mempool events can be dropped or replaced. No confirmation time is predicted.'}</div></section>`;bindCopy();updateSelectedBlockMetrics();updateBlockActivity(blocks);document.querySelectorAll('[data-activity-block]').forEach(button=>button.onclick=()=>document.querySelector('[data-block="'+button.dataset.activityBlock+'"]').click());try{const result=await cached(block?'/api/blocks/'+selected+'/transactions?limit=100':'/api/mempool/events?limit=100');if(g!==generation||panelGeneration!==blockPanelGeneration)return;const entries=block?newestTransactions(arr(result.result)):arr(result.result);$('#block-message-count').textContent=entries.length+(result.next_cursor!=null?' +':'')+(block?(entries.length===1?' transaction':' transactions'):(entries.length===1?' event':' events'));if(!block&&$('#pending-summary'))$('#pending-summary').outerHTML=`<div class="pending-total"><strong>${fmt(entries.length)}${result.next_cursor!=null?'+':''}</strong><span>pending protocol events</span></div>`;$('#block-message-map').innerHTML=entries.length?`<div class="transaction-mosaic">${entries.map((tx,index)=>`<a class="transaction-tile" data-transaction-index="${index}" data-transaction="${esc(tx.tx_hash)}" href="#/${block?'tx':'pending'}/${enc(tx.tx_hash)}" title="${esc(tx.tx_hash)}"><div class="transaction-assets"><span class="transaction-preview-status">Loading asset…</span></div>${tag(tx.transaction_type||tx.event||tx.command)}<span class="mono">${esc(short(tx.tx_hash,6))}</span><small>${block?fmt(tx.btc_amount)+' sats':esc(age(tx.timestamp))}</small></a>`).join('')}</div>`:empty(block?'No ACME transactions indexed in this block':'Mempool is clear',block?'The Bitcoin block can contain transactions that are outside ACME.':'No unconfirmed ACME events were returned.');if(entries.length)enrichTransactionAssets(entries,g,panelGeneration)}catch(error){if(g===generation&&panelGeneration===blockPanelGeneration){$('#block-message-map').innerHTML=empty('Protocol activity unavailable',error.message);if($('#pending-summary'))$('#pending-summary').outerHTML=empty('Mempool unavailable',error.message)}}}
function eventAssets(value,found=new Set(),depth=0){if(depth>8||value==null)return found;if(typeof value==='string'){if(/^[\s]*[\[{]/.test(value)){try{eventAssets(JSON.parse(value),found,depth+1)}catch{}}return found}if(typeof value!=='object')return found;for(const [key,item] of Object.entries(value)){if(['asset','asset_name'].includes(key)&&typeof item==='string'&&item.trim())found.add(item.trim());else if(item&&typeof item==='object'||['bindings','params','data'].includes(key))eventAssets(item,found,depth+1)}return found}
async function enrichTransactionAssets(entries,g,panelGeneration){const source=API;let cursor=0;const current=()=>g===generation&&panelGeneration===blockPanelGeneration&&source===API;const worker=async()=>{while(cursor<entries.length&&current()){const index=cursor++;const tx=entries[index];const tile=[...document.querySelectorAll('.transaction-tile[data-transaction]')].find(el=>el.dataset.transactionIndex===String(index)&&el.dataset.transaction===tx.tx_hash);const slot=tile?.querySelector('.transaction-assets');if(!slot)continue;try{let names=[...eventAssets(tx)];if(!names.length){const events=await cached('/api/transactions/'+enc(tx.tx_hash)+'/events?limit=100',300000);names=[...eventAssets(events.result)]}if(!current()||!slot.isConnected)return;if(!names.length){slot.innerHTML='<span class="transaction-preview-status">No asset in this event</span>';continue}const assets=await Promise.all(names.slice(0,2).map(async name=>{try{const result=await cached('/api/assets/'+enc(name),300000);return {...result.result,asset:name}}catch{return {asset:name}}}));if(!current()||!slot.isConnected)return;slot.innerHTML=assets.map(a=>{const mime=a.art_mime_type||a.mime_type;return `<div class="transaction-asset">${mime?frame(a,96,true):`<div class="transaction-no-art" aria-label="No artwork for ${esc(a.asset)}"><b>${esc(short(a.asset,6))}</b><small>No artwork</small></div>`}<span class="transaction-asset-name" title="${esc(a.asset)}">${esc(a.asset_longname||a.asset)}</span></div>`}).join('')+(names.length>2?`<small>+${names.length-2}</small>`:'');slot.querySelectorAll('.art-frame').forEach(frame=>artworkObserver.observe(frame))}catch{if(current()&&slot.isConnected)slot.innerHTML='<span class="transaction-preview-status">Asset preview unavailable</span>'}}};await Promise.all([worker(),worker(),worker()])}
async function loadTransactionAssetGallery(events,g){const source=API,host=$('#transaction-asset-gallery');if(!host)return;const names=[...eventAssets(events)];const count=$('#transaction-asset-count');if(count)count.textContent='('+names.length+')';if(!names.length){host.innerHTML=empty('No assets referenced','The loaded protocol events do not reference any assets.');return}const assets=new Array(names.length);let cursor=0;const current=()=>g===generation&&source===API&&host.isConnected;const worker=async()=>{while(cursor<names.length&&current()){const index=cursor++,name=names[index];try{const result=await cached('/api/assets/'+enc(name),300000);assets[index]={...result.result,asset:name}}catch{assets[index]={asset:name}}}};await Promise.all([worker(),worker(),worker()]);if(!current())return;host.innerHTML=assets.map(a=>{const name=assetPresentation(a).name||a.asset;return `<a class="transaction-asset-card" href="#/asset/${enc(a.asset)}">${a.art_mime_type||a.mime_type?frame(a,240):`<div class="transaction-no-art"><b>${esc(short(a.asset,12))}</b><small>No artwork available</small></div>`}<strong>${esc(name)}</strong>${name!==a.asset?`<small>${esc(a.asset)}</small>`:''}<span>View asset ↗</span></a>`}).join('');host.querySelectorAll('.art-frame').forEach(frame=>artworkObserver.observe(frame))}
function assetDetailMedia(a){const mime=(a.art_mime_type||a.mime_type||'').split(';')[0].trim().toLowerCase();if(mime!=='text/html'&&mime!=='application/xhtml+xml')return frame(a,900);const src=API+'/api/assets/'+enc(a.asset)+'/content';return `<div class="interactive-asset" data-interactive-key="${esc(API+':'+a.asset)}" data-asset-name="${esc(a.asset)}" data-api-origin="${esc(API)}" data-content-url="${esc(src)}"><div class="interactive-stage"><iframe title="Interactive artwork: ${esc(a.asset)}" sandbox="allow-scripts allow-pointer-lock" allow="fullscreen" allowfullscreen></iframe><div class="interactive-status" role="status">Loading interactive artwork…</div></div><div class="interactive-controls"><span>Interactive artwork</span><button type="button" class="interactive-reload">Reload</button><button type="button" class="interactive-fullscreen">Fullscreen</button><a href="${esc(src)}" target="_blank" rel="noopener">Open original ↗</a></div></div>`}
