const row=(name,value)=>`<div class="detail-row"><span class="detail-key">${name}</span><div>${value}</div></div>`;
const raw=d=>`<details><summary>View API response</summary><pre>${esc(JSON.stringify(d,null,2))}</pre></details>`;
function copy(value){return `<button class="copy" data-copy="${esc(value)}" aria-label="Copy ${esc(short(value))}">Copy</button>`}
function bindCopy(){document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied'}catch{b.textContent='Select text to copy'}})}
async function detail(kind,id,g){const transactionAssetsOpen=$('#transaction-asset-details')?.open||false;const map={asset:`/api/assets/${enc(id)}`,block:`/api/blocks/${enc(id)}`,tx:`/api/transactions/${enc(id)}`,address:`/api/addresses/${enc(id)}/balances?limit=100`,pending:'/api/mempool/events?limit=100'};const d=await cached(map[kind]);if(g!==generation)return;let a=d.result;if(kind==='pending'){const found=arr(a).filter(x=>x.tx_hash===id);if(!found.length){try{return await detail('tx',id,g)}catch{throw Error('This transaction is no longer in the latest mempool events and was not found in the transaction index. It may have confirmed, expired, or been dropped.')}}a=found}
const back={asset:'assets',block:'blocks',tx:'transactions',address:'',pending:'mempool'}[kind];let body='',extra='',subtitle='';
if(!a||(Array.isArray(a)&&a.length===0&&kind!=='address'))throw Error('No matching record was found.');
if(kind==='asset'){try{const rich=await cached('/api/assets/browse?search='+enc(id)+'&limit=100');if(g!==generation)return;const match=arr(rich.result).find(item=>item.asset===a.asset);if(match)a={...a,...match}}catch{}const meta=assetPresentation(a);subtitle=meta.name;body=row('Asset Name',esc(meta.name)+copy(a.asset))+row('Artist Name',meta.artist?link('asset',meta.artist,meta.artist):'Artist not specified')+row('ACME ID','#'+esc(a.asset_id))+row('Owner',a.owner?link('address',a.owner,a.owner):'—')+row('Issuer',a.issuer?link('address',a.issuer,a.issuer):'—')+row('First issuance',link('block',a.first_issuance_block_index,fmt(a.first_issuance_block_index)))+row('Issuance locked',a.locked?'Yes':'No')+row('Media type',esc(a.mime_type))+row('Description',`<p class="asset-description">${esc(a.description||'No description provided.')}</p>`);extra=`<div class="detail-layout asset-detail-layout">${assetDetailMedia(a)}<section class="panel"><div class="asset-detail-caption"><h3>${esc(meta.name)}</h3><p>${meta.artist?'By '+esc(meta.artist):'Artist not specified'}</p><p>ACME ID #${esc(a.asset_id)}</p></div><details class="asset-technical"><summary>More asset details</summary><div class="detail-rows">${body}</div></details>${raw(d)}</section></div><section class="panel cortex-section" aria-label="Asset Cortex Data"><div class="panel-head"><h2>Asset Cortex Data</h2></div><div class="cortex-grid">${['axons','dendrites','tags'].map(type=>`<section class="cortex-column"><div class="cortex-heading"><h3>${type==='axons'?'Axons':type==='dendrites'?'Dendrites':'Tags'}</h3><span id="cortex-${type}-count" class="pill">—</span></div><p class="cortex-description">${type==='axons'?'Outgoing relationships':type==='dendrites'?'Incoming relationships':'Labels attached to this asset'}</p><div id="cortex-${type}" class="cortex-entries">Loading…</div></section>`).join('')}</div></section>`}
if(kind==='block'){subtitle='#'+fmt(a.block_index);body=row('Block height',fmt(a.block_index))+row('Block hash',`<span class="mono">${esc(a.block_hash)}</span>${copy(a.block_hash)}`)+row('Timestamp',esc(date(a.block_time)))+row('Bitcoin transactions',fmt(a.transaction_count))+row('Previous block',link('block',Number(a.block_index)-1,'#'+fmt(Number(a.block_index)-1)))+row('Ledger hash',`<span class="mono">${esc(a.ledger_hash)}</span>`)+row('Messages hash',`<span class="mono">${esc(a.messages_hash)}</span>`);extra=`<section class="panel"><div class="detail-rows">${body}</div>${raw(d)}</section><section class="panel" style="margin-top:22px"><h2 class="subheading">ACME TRANSACTIONS IN THIS BLOCK</h2><div id="related">${empty('Loading block transactions…')}</div></section>`}
if(kind==='tx'){subtitle=short(id,20);const unconfirmed=a.confirmed===false||Number(a.block_index)<0;body=row('Transaction hash',`<span class="mono">${esc(a.tx_hash)}</span>${copy(a.tx_hash)}`)+row('Message type',tag(a.transaction_type))+row('Protocol validity',tag(a.status??(a.valid===true?'valid':'unknown'),a.valid===true))+row('Confirmation',unconfirmed?tag('Unconfirmed'):a.block_index!=null?tag('Indexed in block',true):tag('Unknown'))+row('Block',!unconfirmed&&a.block_index!=null?link('block',a.block_index,'#'+fmt(a.block_index)):'—')+row('Timestamp',esc(date(a.block_time)))+row('Source',link('address',a.source,a.source))+row('Destination',a.destination?link('address',a.destination,a.destination):'—')+row('Bitcoin amount',fmt(a.btc_amount)+' sats')+row('Reported fee',fmt(a.fee)+' sats')+(a.invalid_reason?row('Invalid reason',esc(a.invalid_reason)):'');extra=`<section class="panel"><div class="detail-rows">${body}</div><div class="panel-note">Fee and amount fields are shown exactly as reported by ACME's indexer. Zero may reflect unavailable fee accounting.</div><details class="transaction-asset-details" id="transaction-asset-details" ${transactionAssetsOpen?'open':''}><summary>Relevant assets <span id="transaction-asset-count"></span></summary><div id="transaction-asset-gallery" class="transaction-asset-gallery"><p class="section-description">Loading assets from protocol events…</p></div></details>${raw(d)}</section><section class="panel" style="margin-top:22px"><h2 class="subheading">PROTOCOL EVENTS</h2><div id="related">${empty('Loading transaction events…')}</div></section>`}
if(kind==='address'){subtitle=short(id,17);const balances=arr(a);extra=`<section class="panel"><div class="detail-rows">${row('Bitcoin address',`<span class="mono">${esc(id)}</span>${copy(id)}`)}</div>${balances.length?table(['Asset','Raw quantity','UTXO'],balances.map(b=>`<tr><td>${link('asset',b.asset,b.asset)}</td><td>${fmt(b.quantity)}</td><td class="mono">${esc(b.utxo||'—')}</td></tr>`)):empty('No ACME balances found','This address may still have Bitcoin or activity outside ACME.')}${raw(d)}<div class="panel-note">Up to 100 balances. Quantities are raw API units; divisible assets use 100,000,000 units per asset.</div></section><section class="panel" style="margin-top:22px"><h2 class="subheading">ADDRESS TRANSACTIONS</h2><div id="related">${empty('Loading address transactions…')}</div></section>`}
if(kind==='pending'){subtitle=short(id,18);extra=`<div class="notice">This ACME event is unconfirmed. Mempool presence does not guarantee confirmation.</div><section class="panel"><div class="detail-rows">${row('Transaction hash',`<span class="mono">${esc(id)}</span>${copy(id)}`)}${row('State',tag('Pending'))}${a.map(e=>row('Event',tag(e.event||e.command))+row('First seen',esc(date(e.timestamp)))).join('')}</div>${raw({result:a})}</section>`}
$('#content').innerHTML=`<a class="back" href="#/${back}">← Back to ${back||'overview'}</a><h2 class="page-title">${esc(kind==='tx'?'TRANSACTION':kind.toUpperCase())} <span style="font-size:.65em;font-family:'DM Sans',sans-serif;overflow-wrap:anywhere">${esc(subtitle)}</span></h2><p class="section-description">ACME Protocol · ${esc(network().chain)}</p>${extra}`;restoreInteractiveAssets();images();bindCopy();connection(`Connected to ${new URL(API).hostname} · ${network().name}`,true);
if(kind==='asset')loadAssetCortex(id,g);
if(['block','tx','address'].includes(kind)){let p=kind==='block'?`/api/blocks/${enc(id)}/transactions?limit=20`:kind==='tx'?`/api/transactions/${enc(id)}/events?limit=30`:`/api/addresses/${enc(id)}/transactions?limit=20`;try{const r=await cached(p);if(g!==generation)return;$('#related').innerHTML=kind==='tx'?(arr(r.result).length?raw(r):empty('No protocol events returned')):txRows(arr(r.result))+(r.next_cursor?'<div class="panel-note">Showing the first 20 transactions.</div>':'');if(kind==='tx')loadTransactionAssetGallery(r.result,g)}catch(e){if(g===generation&&$('#related')){$('#related').innerHTML=empty('Related activity unavailable',e.message);if(kind==='tx'&&$('#transaction-asset-gallery'))$('#transaction-asset-gallery').innerHTML=empty('Asset previews unavailable','Reload the page to try again.')}}}}
const cortexPages=new Map();
async function loadAssetCortex(id,g){const source=API;await Promise.all(['axons','dendrites','tags'].map(async type=>{
const endpoint=type==='tags'?'/api/assets/'+enc(id)+'/tags':'/api/cortex/assets/'+enc(id)+'/'+type;const key=source+':'+id+':'+type;let page=cortexPages.get(key)||0,cursor=null,fetched=false,busy=false,pageError='';const entries=new Map(),seen=new Set();const current=()=>g===generation&&source===API&&$('#cortex-'+type);const list=()=>[...entries.values()];
const entryMarkup=entry=>{if(type==='tags'){const value=entry.value??entry.data;return `<div class="cortex-entry"><strong>${esc(entry.tag)}</strong>${value!=null?`<span class="cortex-tag-value">${esc(typeof value==='object'?JSON.stringify(value):value)}</span>`:''}</div>`}const target=type==='axons'?entry.target_ref:entry.source_asset;const linked=type==='dendrites'||['acme','asset'].includes(entry.target_type);return `<div class="cortex-entry"><div class="cortex-relation">${esc(entry.rel_type)}</div><strong>${linked?link('asset',target,target):esc(target)}</strong>${entry.synapse?.status?`<small>${esc(entry.synapse.status)} synapse</small>`:''}</div>`};
const fetchBatch=async()=>{const response=await cached(endpoint+'?limit=100'+(cursor!=null?'&cursor='+enc(cursor):''));if(!current())throw Error('Page changed');const next=response.next_cursor;if(next!=null&&seen.has(String(next)))throw Error('The API repeated its pagination cursor. Please refresh.');if(next!=null)seen.add(String(next));for(const entry of arr(response.result))entries.set(entry.id,entry);cursor=next;fetched=true};
const draw=()=>{if(!current())return;const items=list(),start=page*5;$('#cortex-'+type+'-count').textContent=fmt(items.length)+(cursor!=null?'+':'');$('#cortex-'+type).innerHTML=`<div class="cortex-page-items">${items.length?items.slice(start,start+5).map(entryMarkup).join(''):`<p class="cortex-empty">No ${type} found for this asset.</p>`}</div><div class="cortex-pager"><span>${items.length?`${start+1}–${Math.min(start+5,items.length)} of ${fmt(items.length)}${cursor!=null?'+':''}`:'0 results'}</span><div><button id="cortex-prev-${type}" aria-label="Previous ${type} page" ${page===0||busy?'disabled':''}>←</button><button id="cortex-next-${type}" aria-label="Next ${type} page" ${(start+5>=items.length&&cursor==null)||busy?'disabled':''}>→</button></div></div>${pageError?`<p class="cortex-empty" role="status">${esc(pageError)}</p>`:''}`;$('#cortex-prev-'+type).onclick=()=>{page--;cortexPages.set(key,page);draw()};$('#cortex-next-'+type).onclick=async()=>{if(busy)return;busy=true;pageError='';draw();try{while((page+1)*5>=entries.size&&cursor!=null)await fetchBatch();if(!current())return;if((page+1)*5<entries.size)page++;cortexPages.set(key,page)}catch(error){pageError=error.message}finally{busy=false;if(current())draw()}}};
try{while(!fetched||(entries.size<(page+1)*5&&cursor!=null))await fetchBatch();if(!current())return;page=Math.min(page,Math.max(0,Math.ceil(entries.size/5)-1));cortexPages.set(key,page);draw()}catch(error){if(!current())return;$('#cortex-'+type).innerHTML=`<p class="cortex-empty">${esc(type)} unavailable. ${esc(error.message)}</p><button class="cortex-more" id="cortex-retry-${type}">Retry</button>`;$('#cortex-retry-'+type).onclick=()=>render({quiet:true})}
}))}
async function render({quiet=false}={}){if(quiet&&document.querySelector('.interactive-asset')){updateNetworkSummary();return}discoveryResizeObserver?.disconnect();retainedPreviews=new Map([...document.querySelectorAll('.art-frame[data-preview-key]')].map(frame=>[frame.dataset.previewKey,frame]));const g=++generation;const route=(location.hash.slice(1)||'/').split('?')[0].split('/').filter(Boolean);const kind=route[0]==='section'?'home':route[0]||'home';const sectionTarget=route[0]==='section'?route[1]:null;document.body.classList.toggle('home-page',kind==='home');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(sectionTarget||({asset:'assets',block:'blocks',tx:'transactions',pending:'mempool'}[kind]||kind))));if(!quiet){window.scrollTo({top:0,behavior:'instant'});$('#content').innerHTML='<div class="loading">Loading ACME data…</div>'};try{if(kind==='home'){await home(g);if(!quiet&&g===generation){if(sectionTarget)requestAnimationFrame(()=>document.getElementById('section-'+sectionTarget)?.scrollIntoView({behavior:'instant',block:'start'}));else window.scrollTo({top:0})}}else if(kind==='blocks')await blocksExplorer(g);else if(kind==='tokens')await tokensPage(g);else if(['assets','transactions','mempool'].includes(kind))await listing(kind,g);else if(['asset','block','tx','address','pending'].includes(kind)&&route[1])await detail(kind,decodeURIComponent(route[1]),g);else throw Error('This explorer page does not exist.')}catch(e){if(g!==generation)return;connection('Unable to load this page',false);$('#content').innerHTML=`<a class="back" href="#/">← Back to overview</a><section class="panel">${empty('Could not load this result',e.message)}<div style="text-align:center;padding-bottom:25px"><button class="primary" id="retry">TRY AGAIN</button></div></section>`;$('#retry').onclick=()=>{cache.clear();render()}}}
function submitExplorerSearch(input){const q=input.value.trim();if(!q){input.focus();return}if(/^\d+$/.test(q)){if(!Number.isSafeInteger(Number(q))){input.setCustomValidity('Please enter a valid block height.');input.reportValidity();return}location.hash='/block/'+q}else if(/^[a-f0-9]{64}$/i.test(q))location.hash='/tx/'+q;else if(/^(bc1|tb1|bcrt1|[13][a-km-zA-HJ-NP-Z1-9]{20})/.test(q))location.hash='/address/'+enc(q);else location.hash='/asset/'+enc(q.toUpperCase());input.blur()}
$('#search-form').onsubmit=e=>{e.preventDefault();submitExplorerSearch($('#search'))};$('#header-search-form').onsubmit=e=>{e.preventDefault();submitExplorerSearch($('#header-search'))};for(const input of [$('#search'),$('#header-search')])input.oninput=()=>input.setCustomValidity('');

const focusSearch=()=>{(document.body.classList.contains('home-page')?$('#search'):$('#header-search')).focus();window.scrollTo({top:0,behavior:'smooth'})};$('#footer-search').onclick=focusSearch;document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();focusSearch()}});
$('#latest-example').onclick=()=>{if(lastStatus)location.hash='/block/'+lastStatus.block_index;else location.hash='/blocks'};
$('#refresh').onclick=()=>{cache.clear();render({quiet:true})};$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'▷ Resume':'Ⅱ Pause';$('#pause').setAttribute('aria-pressed',String(paused));if(!paused){cache.clear();render({quiet:true})}};try{document.body.classList.toggle('dark',localStorage.getItem('acme-theme')==='dark')}catch{}function syncThemeToggle(){const dark=document.body.classList.contains('dark');const button=$('#theme');button.innerHTML=dark?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M4.93 4.93l1.41 1.41m11.32 11.32 1.41 1.41M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.9 13.1A9 9 0 0 1 10.9 3.1 9 9 0 1 0 20.9 13.1Z"/></svg>';const label=dark?'Switch to light mode':'Switch to dark mode';button.setAttribute('aria-label',label);button.title=label;document.documentElement.style.colorScheme=dark?'dark':'light'}syncThemeToggle();$('#theme').onclick=()=>{document.body.classList.toggle('dark');syncThemeToggle();try{localStorage.setItem('acme-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}};function syncNetworkUI(){document.querySelectorAll('[data-network]').forEach(button=>{button.setAttribute('aria-pressed',String(button.dataset.network===selectedNetwork))});document.body.classList.toggle('testnet',selectedNetwork==='testnet');$('#network-chain').textContent=network().chain;$('#network-eyebrow').textContent='ACME PROTOCOL · '+network().chain.toUpperCase();$('#footer-network').textContent=network().chain.toUpperCase();document.title='ACME Scan — '+network().name+' Explorer';document.querySelectorAll('[data-network-link]').forEach(anchor=>{anchor.href=API+(anchor.dataset.networkLink==='docs'?'/docs/':'/');if(anchor.hasAttribute('data-network-app-label'))anchor.textContent=network().name+' app ↗'})}
async function updateNetworkSummary(){const source=API;const results=await Promise.allSettled([cached('/api/status'),cached('/api/bitcoin/estimatesmartfee?conf_target=6')]);if(source!==API)return;if(results[0].status==='fulfilled'){lastStatus=results[0].value.result;$('#top-block').textContent=fmt(lastStatus?.block_index)}if(results[1].status==='fulfilled'){const fee=results[1].value.result;$('#top-fee').textContent=fee?.feerate!=null?fmt(fee.feerate*1e5)+' sat/vB':'—'}}
function changeNetwork(next){if(!Object.hasOwn(NETWORKS,next)||next===selectedNetwork)return;generation++;networkController.abort();networkController=new AbortController();document.querySelectorAll('.art-frame').forEach(frame=>frame.artworkController?.abort());artworkObserver.disconnect();artworkQueue.length=0;retainedPreviews.clear();cache.clear();lastStatus=null;selectedNetwork=next;API=network().api;try{localStorage.setItem('acme-network',next)}catch{}const target=new URL(location.href);target.searchParams.set('network',next);const section=(target.hash.slice(1)||'/').split('?')[0].split('/').filter(Boolean)[0];target.hash=['assets','blocks','transactions','mempool','tokens'].includes(section)?'/'+section:'/';window.history.replaceState(null,'',target);$('#content').innerHTML='';$('#top-block').textContent='—';$('#top-fee').textContent='—';$('#updated').textContent='';$('#connection').textContent='Connecting to '+network().name+'…';syncNetworkUI();updateNetworkSummary();render()}
document.querySelectorAll('[data-network]').forEach(button=>button.onclick=()=>changeNetwork(button.dataset.network));syncNetworkUI();updateNetworkSummary();

window.addEventListener('hashchange',()=>{const match=location.hash.match(/^#\/section\/(blocks|transactions|assets|tokens|mempool)$/);if(match&&document.body.classList.contains('home-page')&&document.getElementById('section-'+match[1])){document.getElementById('section-'+match[1]).scrollIntoView({behavior:'smooth',block:'start'});document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===match[1]));return}render()});setInterval(()=>{if(!paused&&!document.hidden)render({quiet:true})},30000);render();
